# The one-command install, shared by the Install page and the landing page (index.html), so the two cannot
# drift apart. It downloads the latest release, checks its SHA-256 checksum, and runs the installer.
# HTML-escaped, ready for a <code> block.
INSTALL_COMMAND = '''cd "$(mktemp -d)" &amp;&amp; tag="$(curl -fsSIL -o /dev/null -w '%{url_effective}' https://github.com/deansasek/library/releases/latest | sed 's#.*/tag/##')" &amp;&amp; ver="${tag#v}" &amp;&amp; curl -fsSL -O "https://github.com/deansasek/library/releases/download/$tag/Library-$ver.zip" -O "https://github.com/deansasek/library/releases/download/$tag/Library-$ver.zip.sha256" &amp;&amp; shasum -a 256 -c "Library-$ver.zip.sha256" &amp;&amp; unzip -q "Library-$ver.zip" &amp;&amp; "./Library-$ver/install.sh"'''


def release_page(page, r):
    """One page per large release: summary, sidebar contents, sections, download line, Related."""
    toc = [(re.sub(r'[^a-z0-9]+', '-', h.lower()).strip('-'), h) for h, _ in r['sections']]
    toc.append(('download', 'Download'))
    sections = []
    for h, items in r['sections']:
        sid = re.sub(r'[^a-z0-9]+', '-', h.lower()).strip('-')
        sections.append((sid, h, '<ul>' + ''.join(f'<li>{i}</li>' for i in items) + '</ul>'))
    tag = r['tag']
    download = (f'<p>Download Library {r["version"]} from the <a href="https://github.com/deansasek/library/releases/tag/{_html.escape(tag)}" '
                'rel="noopener noreferrer">GitHub release page</a>, or install it with the command on the <a href="/install/">install page</a>.</p>')
    sections.append(('download', 'Download', download))
    return page('/whats-new/' + r['id'] + '/', f"What's new in Library {r['version']}", f"{r['summary']} Released {r['date']}.", r['intro'], toc, sections,
                released=r['date'])


# The guide's side navigation: six groups by what people are trying to do. Each feature lists its sub-sections
# under it, so a group shows a handful of entries at a time. Every guide section id belongs to exactly one group.
GUIDE_GROUPS = [
    ('Get started', 'Install Library, then learn the first steps.', ['get-started']),
    ('Find and open', 'Open items from the menu bar, Quick Open, a shortcut, or the Library menu.',
     ['open-anything', 'quick-open', 'the-library-menu', 'shortcuts']),
    ('Copy and paste', 'The clipboard history, the paste queue, and the actions on copied items.', ['clipboard']),
    ('Organize', 'Edit Library, colors, and notes.', ['manager', 'color-items', 'add-notes']),
    ('Snippets and automation', 'Snippets, the URL scheme, Services, and Spotlight.',
     ['save-snippets', 'integration']),
    ('Settings, privacy, and help', 'Every setting, the permissions Library asks for, updates, and troubleshooting.',
     ['settings', 'storage', 'permissions', 'stay-up-to-date', 'help-menu', 'troubleshooting']),
]

# Section id -> the page that holds it, and section id -> group title. Filled in by guide_pages().
GUIDE_PATH_OF = {}
GUIDE_GROUP_OF = {}
GROUP_INTRO = {title: intro for title, intro, _ in GUIDE_GROUPS}


def group_slug(title):
    return re.sub(r'[^a-z0-9]+', '-', title.lower()).strip('-')


def guide_navigation(labels, subs, current):
    """The guide's side navigation: every group, its features, and their sub-sections folded under each feature.

    Links to the current group's sections stay on the page. Links to other groups go to their pages.
    The current group is open.
    """
    parts = []
    for title, _, ids in GUIDE_GROUPS:
        here = title == current

        def href(i):
            return f'#{i}' if here else f'{GUIDE_PATH_OF[i]}#{i}'

        items = []
        for t in ids:
            if subs[t]:
                inner = ''.join(f'<li><a href="{href(i)}">{l}</a></li>' for i, l in subs[t])
                items.append(f'<li><details><summary><a href="{href(t)}">{labels[t]}</a></summary><ol>{inner}</ol></details></li>')
            else:
                items.append(f'<li><a href="{href(t)}">{labels[t]}</a></li>')
        opened = ' open' if here else ''
        parts.append(f'<details class="group"{opened}><summary>{title}</summary><p class="group-intro">{GROUP_INTRO[title]}</p>'
                     f'<ol>{"".join(items)}</ol></details>')
    return '<div class="guide-nav">' + ''.join(parts) + '</div>'


def guide_pages(toc, sections, page):
    """The guide as one page per group, plus an index that lists the groups. Returns {url path: html}.

    Every section lives on exactly one page. Links to a section on another page are rewritten to that page.
    """
    section_ids = {i for i, _, _ in sections}
    tops = [i for _, _, ids in GUIDE_GROUPS for i in ids]
    if len(set(tops)) != len(tops) or not set(tops) <= section_ids:
        raise SystemExit('GUIDE_GROUPS must name each top-level guide section once, and only real sections')
    labels, subs, current = {}, {i: [] for i in tops}, None
    for i, label in toc:
        if i in tops:
            labels[i], current = label, i
        else:
            subs[current].append((i, label.split(': ', 1)[-1]))
    GUIDE_PATH_OF.clear()
    GUIDE_GROUP_OF.clear()
    for title, _, ids in GUIDE_GROUPS:
        for t in ids:
            for i in [t] + [s for s, _ in subs[t]]:
                GUIDE_PATH_OF[i] = f'/guide/{group_slug(title)}/'
                GUIDE_GROUP_OF[i] = title
    missing = section_ids - set(GUIDE_PATH_OF)
    if missing:
        raise SystemExit('guide sections missing from the navigation: ' + ', '.join(sorted(missing)))

    def rewrite(html, path):
        return re.sub(r'href="#([a-z0-9-]+)"',
                      lambda m: f'href="{GUIDE_PATH_OF[m.group(1)]}#{m.group(1)}"'
                      if GUIDE_PATH_OF.get(m.group(1), path) != path else m.group(0), html)

    out, index_toc, index_sections = {}, [], []
    for title, intro, ids in GUIDE_GROUPS:
        slug = group_slug(title)
        path = f'/guide/{slug}/'
        body = [(i, h, rewrite(html, path)) for i, h, html in sections if GUIDE_GROUP_OF[i] == title]
        feats = ''.join(f'<li><a href="{path}#{t}">{labels[t]}</a></li>' for t in ids)
        index_toc.append((f'group-{slug}', title))
        index_sections.append((f'group-{slug}', title, f'<p>{intro}</p><ol>{feats}</ol>'))
        desc = f'{intro} Covers {", ".join(labels[t] for t in ids)}.'
        if len(desc) > 160:
            desc = f'{intro} Covers {", ".join(labels[t] for t in ids[:3])}, and more.'
        if len(desc) < 70:
            desc += ' Part of the Library guide.'
        out[path + 'index.html'] = page(path, f'{title}: Library guide', desc, intro,
                                        [(i, h) for i, h, _ in body], body,
                                        nav=guide_navigation(labels, subs, title))
    out['/guide/index.html'] = page('/guide/', 'Library guide: features, settings, and permissions',
                                    'Every feature, setting, and permission in Library, grouped by what you want to do: open, copy, organize, automate, and configure.',
                                    'Every feature, setting, and permission in Library, with the steps to use each one.',
                                    index_toc, index_sections)
    return out




def _release_records():
    """The published releases from content/releases.json, newest first. Empty when the file is missing."""
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'releases.json')
    try:
        with open(path) as f:
            return json.load(f)
    except FileNotFoundError:
        return []


def release_history(minor_ids, limit=None, curated=None):
    """Every published Library release, newest first, from content/releases.json (written by tools/sync_releases.py).

    Each release gets its date, its changes, and a link to the GitHub release. Releases with a What's new page
    link to it too.
    """
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'releases.json')
    try:
        with open(path) as f:
            releases = json.load(f)
    except FileNotFoundError:
        return '<p>The release list is not available right now. See <a href="https://github.com/deansasek/library/releases" rel="noopener noreferrer">all releases on GitHub</a>.</p>'
    out = []
    for r in releases:
        date = datetime.date.fromisoformat(r['date']).strftime('%B %-d, %Y')
        wn_id = r['version'].replace('.', '-')
        # The changes shown and counted are the ones on the release's What's new page, so the two always agree.
        notes = curated[r['version']] if curated and r['version'] in curated else r['notes']
        shown = notes if limit is None else notes[:limit]
        items = ''.join(f'<li>{_html.escape(n)}</li>' for n in shown)
        changes = f'<ul>{items}</ul>' if items else '<p>No changes listed.</p>'
        # A long release shows only its first changes here; the What's new page has all of them.
        if len(notes) > len(shown):
            changes += f'<p><a href="/whats-new/{wn_id}/">See all {len(notes)} changes in What\'s new</a></p>'
        whats_new = f' <a href="/whats-new/{wn_id}/">What\'s new</a>.' if wn_id in minor_ids else ''
        out.append(f'<section class="release" id="{_html.escape(r["tag"])}">'
                   f'<h2><a href="{_html.escape(r["url"])}" rel="noopener noreferrer">Library {_html.escape(r["version"])}</a></h2>'
                   f'<p class="updated">Released {date}.{whats_new}</p>{changes}</section>')
    return ''.join(out)


